package store

// selectWKDKeys is LookupWKDKey's serving rule (#795, ADR-040), tested without
// a database. Keys are generated by go-crypto.

import (
	"bytes"
	"testing"
	"time"

	"github.com/ProtonMail/go-crypto/openpgp"
	"github.com/ProtonMail/go-crypto/openpgp/packet"
)

func wkdTestKey(t *testing.T, created time.Time, lifetime time.Duration, revoke bool) []byte {
	t.Helper()
	e, err := openpgp.NewEntity("W", "", "w@example.com", &packet.Config{
		Algorithm: packet.PubKeyAlgoEdDSA, Curve: packet.Curve25519,
		Time:            func() time.Time { return created },
		KeyLifetimeSecs: uint32(lifetime / time.Second),
	})
	if err != nil {
		t.Fatal(err)
	}
	if revoke {
		if err := e.RevokeKey(packet.KeyRetired, "", &packet.Config{Time: func() time.Time { return created }}); err != nil {
			t.Fatal(err)
		}
	}
	var buf bytes.Buffer
	if err := e.Serialize(&buf); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func TestSelectWKDKeys(t *testing.T) {
	now := time.Now()
	live := wkdRow{address: "w@example.com", pub: wkdTestKey(t, now.Add(-time.Hour), 0, false), fpr: "LIVE"}
	older := wkdRow{address: "w@example.com", pub: wkdTestKey(t, now.Add(-2*time.Hour), 0, false), fpr: "OLDER"}
	expired := wkdRow{address: "w@example.com", pub: wkdTestKey(t, now.Add(-40*24*time.Hour), 30*24*time.Hour, false), fpr: "EXPIRED"}
	revoked := wkdRow{address: "w@example.com", pub: wkdTestKey(t, now.Add(-3*time.Hour), 0, true), fpr: "REVOKED"}
	junk := wkdRow{address: "w@example.com", pub: []byte{0x99, 0x01, 0x02}, fpr: "JUNK"}

	cat := func(rs ...wkdRow) []byte {
		var b []byte
		for _, r := range rs {
			b = append(b, r.pub...)
		}
		return b
	}
	cases := []struct {
		name    string
		rows    []wkdRow
		found   bool
		fpr     string
		body    []byte
		revOnly bool
	}{
		{"one live key", []wkdRow{live}, true, "LIVE", cat(live), false},
		{"newest live wins", []wkdRow{live, older}, true, "LIVE", cat(live), false},
		{"expired newest is skipped for the next live one", []wkdRow{expired, older}, true, "OLDER", cat(older), false},
		{"only an expired key: nothing", []wkdRow{expired}, false, "", nil, false},
		{"live then revocation", []wkdRow{live, revoked}, true, "LIVE", cat(live, revoked), false},
		{"only a revocation is still served", []wkdRow{revoked}, true, "REVOKED", cat(revoked), true},
		{"expired plus revocation serves the revocation", []wkdRow{expired, revoked}, true, "REVOKED", cat(revoked), true},
		{"unreadable rows are never served", []wkdRow{junk}, false, "", nil, false},
		{"no rows", nil, false, "", nil, false},
	}
	for _, c := range cases {
		got, found := selectWKDKeys(c.rows, now)
		if found != c.found || got.Fingerprint != c.fpr || !bytes.Equal(got.PublicKey, c.body) || got.RevocationsOnly != c.revOnly {
			t.Errorf("%s: found=%v fpr=%q revOnly=%v body-match=%v", c.name, found, got.Fingerprint,
				got.RevocationsOnly, bytes.Equal(got.PublicKey, c.body))
		}
	}
}
